+#if defined(HAS_ENGINE_KMOD) || defined(HAS_ENGINE_MODERN_BPF)
+static bool
+get_bool_value(const char *bool_str)
+{
+    if (!bool_str) {
+        return false;
+    }
+    switch (bool_str[0]) {
+        case 'f':
+        case 'F':
+        case '0':
+            return false;
+            break;
+        default:
+            return true;
+    }
+}
